/**
 * Art — one picture from the Practice art (Doh the doh bird, the level emblems, the badge stickers, the flame, the
 * stars, the confetti, the track scenes and the empty states), drawn by react-native-svg's SvgXml from the strings in
 * `art/svgs.ts` (generated by design/practice-art/build.mjs; no native module, so it ships over the air).
 *
 * Decorative: the text beside it says what it shows, so screen readers skip it. Give a width; the height follows the
 * picture's own proportions unless one is given.
 */

import React, { memo } from "react";
import type { StyleProp, ViewStyle } from "react-native";
import { SvgXml } from "react-native-svg";

import { ART, type ArtName } from "./art/svgs";

const VIEW_BOX = /viewBox=['"]0 0 ([\d.]+) ([\d.]+)['"]/;

/** Height over width, from the picture's viewBox. */
export function artRatio(name: ArtName): number {
  const m = VIEW_BOX.exec(ART[name]);
  return m ? Number(m[2]) / Number(m[1]) : 1;
}

interface Props {
  name: ArtName;
  width: number;
  height?: number;
  style?: StyleProp<ViewStyle>;
}

export const Art = memo(function Art({ name, width, height, style }: Props) {
  return (
    <SvgXml
      xml={ART[name]}
      width={width}
      height={height ?? Math.round(width * artRatio(name))}
      style={style}
      accessibilityElementsHidden
      importantForAccessibility="no-hide-descendants"
      pointerEvents="none"
    />
  );
});
